/**
 * Emits lib/client.js — the browser half — from tools/tokens.json.
 *
 * The client bundle is a plain `window.__ModuleLoader__.load({ factory })` CJS
 * module, which is exactly what the Loader's lazy module table expects. Because
 * a colour theme needs no React, no JSX and no stylesheet import, this file is
 * generated by string assembly rather than by a bundler: there is nothing to
 * bundle. That keeps the whole plugin installable straight from a checkout,
 * with no `pnpm run build` step in the loop.
 *
 * The palette itself is data (tools/tokens.json); this script never invents a
 * colour, so regenerating after a DSH upgrade cannot silently drift.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = join(HERE, '..')

const pkg = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'))
const tokens = JSON.parse(readFileSync(join(HERE, 'tokens.json'), 'utf8'))

const names = Object.keys(tokens)
if (names.length === 0) throw new Error('tokens.json is empty')

/** Sort statics before semantic tokens so the generated file reads top-down. */
const ordered = names.sort((a, b) => {
  const rank = (n) => (n.startsWith('--dsw-static-') ? 0 : 1)
  return rank(a) - rank(b) || a.localeCompare(b)
})

const rows = ordered.map((name) => {
  const { light, dark } = tokens[name]
  if (typeof light !== 'string' || typeof dark !== 'string') {
    throw new Error(`token ${name} is missing a light/dark pair`)
  }
  for (const [mode, value] of [['light', light], ['dark', dark]]) {
    if (!/^#[0-9a-f]{3,8}$/i.test(value) && !/^(rgb|hsl|oklch|color)\(/i.test(value)) {
      throw new Error(`token ${name} has a non-colour ${mode} value: ${value}`)
    }
  }
  return `\t\t\t${JSON.stringify(name)}: { light: ${JSON.stringify(light)}, dark: ${JSON.stringify(dark)} },`
}).join('\n')

const source = `/**
 * GENERATED by tools/build-client.mjs from tools/tokens.json — do not edit by
 * hand. Run \`node tools/palette.mjs && node tools/build-client.mjs\` to
 * regenerate the palette and this bundle together.
 *
 * ${pkg.description}
 *
 * The whole plugin is one token override layer: \`ctx.theme.overrideTokens\`
 * stacks these --dsw-* variables over whichever built-in palette the user has
 * selected, and the presenter writes them to <body> as inline custom
 * properties. Two consequences worth knowing before changing anything here:
 *
 *   - The override is scheme-aware. Each token carries both a light and a dark
 *     value, and the presenter emits the one matching the resolved colour
 *     scheme, so a token can never go illegible when the user flips their
 *     preference.
 *   - The override is reversible. \`overrideTokens\` returns its own disposer and
 *     this module hands that disposer to \`ctx.effect\`, so unloading the plugin
 *     (or a hot reload) retracts exactly the layer it added.
 */
window.__ModuleLoader__.load({
\tid: ${JSON.stringify(pkg.name)},
\tfactory: () => {
\t\tvar module = { exports: {} };
\t\tvar exports = module.exports;
\t\tObject.defineProperty(exports, Symbol.toStringTag, { value: "Module" });

\t\t/**
\t\t * Layer identity. One layer per source: registering again under the same
\t\t * source replaces the whole layer and restacks it, which is what makes a
\t\t * hot reload idempotent instead of additive.
\t\t */
\t\tconst SOURCE = ${JSON.stringify(pkg.name)};

\t\t/**
\t\t * The palette. Raw --dsw-static-* ramp members come first, then every
\t\t * semantic token whose resolved colour this theme changes — so components
\t\t * that read a ramp directly and components that read a semantic alias both
\t\t * land on the same palette.
\t\t */
\t\tconst TOKENS = {
${rows}
\t\t};

\t\t/**
\t\t * Required service. \`theme\` is owned by @deepseek-ai/dsh-client-ui-theme,
\t\t * which ui-layout (mandatory in every web composition) already hard-depends
\t\t * on, so requiring it cannot keep this plugin unmounted on a working host.
\t\t */
\t\tconst inject = ["theme"];

\t\t/**
\t\t * Client plugin body: stack the palette as one override layer.
\t\t * @param ctx - client cordis context.
\t\t */
\t\tfunction apply(ctx) {
\t\t\tif (typeof ctx.theme?.overrideTokens !== "function") {
\t\t\t\tconsole.warn("[inkstone] host theme service has no overrideTokens — theme not applied (dsh web >= 0.1.5-rc.1 required)");
\t\t\t\treturn;
\t\t\t}
\t\t\tctx.effect(
\t\t\t\t() => ctx.theme.overrideTokens(SOURCE, TOKENS),
\t\t\t\tSOURCE + ": palette overrides",
\t\t\t);
\t\t}

\t\texports.apply = apply;
\t\texports.inject = inject;
\t\treturn module.exports;
\t},
});
`

mkdirSync(join(ROOT, 'lib'), { recursive: true })
writeFileSync(join(ROOT, 'lib/client.js'), source)
console.log(`wrote lib/client.js (${ordered.length} tokens, ${source.length} bytes)`)
